/* Wave glow follows the kart root with an external local-space offset.
 * Local views contain only target-observed fields. Aggregate arguments use
 * caller-owned copies; exception metadata is generated by the compiler.
 */
struct WaveGlowVec3 { float x, y, z; };
struct WaveGlowEffect {
    unsigned char pad00[0x14];
    unsigned char slot[0xA];
    signed char finished;
    unsigned char pad1F[9];
    unsigned char visible;
    unsigned char pad29[0x63];
    WaveGlowVec3 position;
    unsigned char pad98[0x18];
    float scale;
    signed char state;
    unsigned char padB5[0x67];
    void *kart;
};
extern "C" {
extern const WaveGlowVec3 lbl_8032A748;
extern const float lbl_806D540C, lbl_806D5424;
void DrawEffect_Free(WaveGlowEffect *);
void VfxSlot_BindResourceEx(void *, int, int);
void VfxSlot_SetAnimSpeed(void *, float);
void VfxSlot_SetScaleUniform(void *, float);
void *KartDriver_GetKartRootMtx(void *);
void Mtx_TransposeToMtx44(float *, const void *);
void Mtx44_TransformVec3(WaveGlowVec3 *, const float *, WaveGlowVec3);
void VfxSlot_SetPositionFromVec(void *, WaveGlowVec3);
unsigned char FinalLapCoinJump_CheckActiveForObject(void *);

void Effect_KartWaveGlow_Update(WaveGlowEffect *effect) {
    float matrix[16];
    switch (effect->state) {
    case 0:
        if (effect->kart == 0) {
            DrawEffect_Free(effect);
            return;
        }
        VfxSlot_BindResourceEx(effect->slot, 0x64, 0);
        VfxSlot_SetAnimSpeed(effect->slot, lbl_806D540C);
        effect->scale = lbl_806D5424;
        VfxSlot_SetScaleUniform(effect->slot, effect->scale);
        ++effect->state;
        break;
    case 1:
        break;
    }
    if (effect->finished == 1) {
        DrawEffect_Free(effect);
        return;
    }
    Mtx_TransposeToMtx44(matrix, KartDriver_GetKartRootMtx(effect->kart));
    Mtx44_TransformVec3(&effect->position, matrix, lbl_8032A748);
    VfxSlot_SetPositionFromVec(effect->slot, effect->position);
    if (FinalLapCoinJump_CheckActiveForObject(effect->kart)) effect->visible = 0;
    else effect->visible = 1;
}
}
